+import type { AnyColumn } from '~/column.ts';
+import { SQL, sql, type SQLWrapper } from '../sql.ts';
+
+export type WindowOrderBy = SQLWrapper | readonly SQLWrapper[];
+
+export type WindowBoundary =
+	| { readonly type: 'unboundedPreceding' }
+	| { readonly type: 'preceding'; readonly value: number }
+	| { readonly type: 'currentRow' }
+	| { readonly type: 'following'; readonly value: number }
+	| { readonly type: 'unboundedFollowing' };
+
+export interface WindowFrame {
+	readonly type: 'rows' | 'range';
+	readonly from: WindowBoundary;
+	readonly to: WindowBoundary;
+}
+
+export interface WindowSpec {
+	partitionBy?: SQLWrapper | readonly SQLWrapper[];
+	orderBy?: WindowOrderBy;
+	frame?: WindowFrame;
+}
+
+export interface WindowDefinition {
+	readonly name: string;
+	readonly spec: WindowSpec;
+}
+
+export const unboundedPreceding: WindowBoundary = { type: 'unboundedPreceding' };
+export const currentRow: WindowBoundary = { type: 'currentRow' };
+export const unboundedFollowing: WindowBoundary = { type: 'unboundedFollowing' };
+
+function position(value: number, helper: 'preceding' | 'following'): WindowBoundary {
+	if (!Number.isInteger(value) || value < 0) {
+		throw new Error(`${helper}() requires a non-negative integer, received ${value}`);
+	}
+	return { type: helper, value };
+}
+
+export function preceding(value: number): WindowBoundary {
+	return position(value, 'preceding');
+}
+
+export function following(value: number): WindowBoundary {
+	return position(value, 'following');
+}
+
+function boundaryOrder(boundary: WindowBoundary): number {
+	switch (boundary.type) {
+		case 'unboundedPreceding': return 0;
+		case 'preceding': return 1;
+		case 'currentRow': return 2;
+		case 'following': return 3;
+		case 'unboundedFollowing': return 4;
+	}
+}
+
+function frame(type: WindowFrame['type'], spec: { from: WindowBoundary; to: WindowBoundary }): WindowFrame {
+	if (boundaryOrder(spec.from) > boundaryOrder(spec.to)) {
+		throw new Error('Window frame "from" boundary cannot be ordered after "to" boundary');
+	}
+	return { type, ...spec };
+}
+
+export function rows(spec: { from: WindowBoundary; to: WindowBoundary }): WindowFrame {
+	return frame('rows', spec);
+}
+
+export function range(spec: { from: WindowBoundary; to: WindowBoundary }): WindowFrame {
+	return frame('range', spec);
+}
+
+function renderBoundary(boundary: WindowBoundary): SQL {
+	switch (boundary.type) {
+		case 'unboundedPreceding': return sql.raw('unbounded preceding');
+		case 'preceding': return sql.raw(`${boundary.value} preceding`);
+		case 'currentRow': return sql.raw('current row');
+		case 'following': return sql.raw(`${boundary.value} following`);
+		case 'unboundedFollowing': return sql.raw('unbounded following');
+	}
+}
+
+export function buildWindowSpec(spec: WindowSpec): SQL {
+	const chunks: SQL[] = [];
+	if (spec.partitionBy) {
+		const partitionBy = Array.isArray(spec.partitionBy) ? spec.partitionBy : [spec.partitionBy];
+		chunks.push(sql`partition by ${sql.join([...partitionBy], sql`, `)}`);
+	}
+	if (spec.orderBy) {
+		const orderBy = Array.isArray(spec.orderBy) ? spec.orderBy : [spec.orderBy];
+		chunks.push(sql`order by ${sql.join([...orderBy], sql`, `)}`);
+	}
+	if (spec.frame) {
+		chunks.push(sql`${sql.raw(spec.frame.type)} between ${renderBoundary(spec.frame.from)} and ${renderBoundary(spec.frame.to)}`);
+	}
+	return sql.join(chunks, sql` `);
+}
+
+export function buildWindowDefinitions(definitions: readonly WindowDefinition[] | undefined): SQL | undefined {
+	if (!definitions?.length) return undefined;
+	return sql` window ${sql.join(definitions.map(({ name, spec }) => sql`${sql.identifier(name)} as (${buildWindowSpec(spec)})`), sql`, `)}`;
+}
+
+export class WindowFunction<T> implements SQLWrapper {
+	constructor(private readonly expression: SQL<T>) {}
+
+	over(spec: WindowSpec | string = {}): SQL<T> {
+		return typeof spec === 'string'
+			? sql`${this.expression} over ${sql.identifier(spec)}`.mapWith(this.expression.decoder)
+			: sql`${this.expression} over (${buildWindowSpec(spec)})`.mapWith(this.expression.decoder);
+	}
+
+	getSQL(): SQL<T> {
+		return this.expression;
+	}
+}
+
+type ValueOf<T extends SQLWrapper> = T extends AnyColumn ? T['_']['data'] : T extends SQL<infer TValue> ? TValue : unknown;
+
+function windowFunction<T>(name: string, args: SQLWrapper[] = []): WindowFunction<T> {
+	return new WindowFunction(sql`${sql.raw(name)}(${sql.join(args, sql`, `)})`);
+}
+
+function positiveInteger(functionName: string, value: number): void {
+	if (!Number.isInteger(value) || value <= 0) {
+		throw new Error(`${functionName}() requires a positive integer, received ${value}`);
+	}
+}
+
+export function rowNumber(): WindowFunction<number> { return windowFunction('row_number'); }
+export function rank(): WindowFunction<number> { return windowFunction('rank'); }
+export function denseRank(): WindowFunction<number> { return windowFunction('dense_rank'); }
+export function ntile(buckets: number): WindowFunction<number> {
+	positiveInteger('ntile', buckets);
+	return windowFunction('ntile', [sql.raw(String(buckets))]);
+}
+export function percentRank(): WindowFunction<number> { return windowFunction('percent_rank'); }
+export function cumeDist(): WindowFunction<number> { return windowFunction('cume_dist'); }
+
+export function lag<T extends SQLWrapper>(expression: T, offset?: number): WindowFunction<ValueOf<T> | null>;
+export function lag<T extends SQLWrapper>(expression: T, offset: number | undefined, defaultValue: ValueOf<T>): WindowFunction<Exclude<ValueOf<T>, null>>;
+export function lag<T extends SQLWrapper>(expression: T, offset?: number, defaultValue?: ValueOf<T>): WindowFunction<ValueOf<T> | null> {
+	const args: SQLWrapper[] = [expression];
+	if (offset !== undefined) args.push(sql.raw(String(offset)));
+	if (defaultValue !== undefined) args.push(sql`${defaultValue}`);
+	return windowFunction('lag', args);
+}
+
+export function lead<T extends SQLWrapper>(expression: T, offset?: number): WindowFunction<ValueOf<T> | null>;
+export function lead<T extends SQLWrapper>(expression: T, offset: number | undefined, defaultValue: ValueOf<T>): WindowFunction<Exclude<ValueOf<T>, null>>;
+export function lead<T extends SQLWrapper>(expression: T, offset?: number, defaultValue?: ValueOf<T>): WindowFunction<ValueOf<T> | null> {
+	const args: SQLWrapper[] = [expression];
+	if (offset !== undefined) args.push(sql.raw(String(offset)));
+	if (defaultValue !== undefined) args.push(sql`${defaultValue}`);
+	return windowFunction('lead', args);
+}
+
+export function firstValue<T extends SQLWrapper>(expression: T): WindowFunction<ValueOf<T> | null> { return windowFunction('first_value', [expression]); }
+export function lastValue<T extends SQLWrapper>(expression: T): WindowFunction<ValueOf<T> | null> { return windowFunction('last_value', [expression]); }
+export function nthValue<T extends SQLWrapper>(expression: T, nth: number): WindowFunction<ValueOf<T> | null> {
+	positiveInteger('nthValue', nth);
+	return windowFunction('nth_value', [expression, sql.raw(String(nth))]);
+}
+
+export function windowSum<T extends SQLWrapper>(expression: T): WindowFunction<string | null> { return windowFunction('sum', [expression]); }
+export function windowAvg<T extends SQLWrapper>(expression: T): WindowFunction<string | null> { return windowFunction('avg', [expression]); }
+export function windowMin<T extends SQLWrapper>(expression: T): WindowFunction<ValueOf<T> | null> { return windowFunction('min', [expression]); }
+export function windowMax<T extends SQLWrapper>(expression: T): WindowFunction<ValueOf<T> | null> { return windowFunction('max', [expression]); }
+export function windowCount(expression?: SQLWrapper): WindowFunction<number> { return windowFunction('count', expression ? [expression] : [sql.raw('*')]); }
